    private void addNativeProductSearch(){
        EditText search=input("חיפוש מוצרים ומלאי");content.addView(search,0);final LinearLayout host=content;
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence value,int a,int b,int c){String q=value.toString().trim().toLowerCase(Locale.ROOT);for(int i=1;i<host.getChildCount();i++){View row=host.getChildAt(i);if(row instanceof LinearLayout){LinearLayout box=(LinearLayout)row;if(box.getChildCount()>0&&box.getChildAt(0) instanceof TextView&&!(box.getChildAt(0) instanceof Button)){String txt=((TextView)box.getChildAt(0)).getText().toString().toLowerCase(Locale.ROOT);row.setVisibility(q.isEmpty()||txt.contains(q)?View.VISIBLE:View.GONE);}}else if(row instanceof TextView&&!(row instanceof Button)&&!(row instanceof EditText))row.setVisibility(q.isEmpty()?View.VISIBLE:View.GONE);}}});
    }
    private JSONObject managementFilters=new JSONObject();
    private int managementPage=0,managementSort=0,managementRevision=0;
    private LinearLayout managementResults;
    private void showSalesHistoryNative(){
        buildShell("סיכום מכירות ומוצרים",this::showReports,false);
        LinearLayout tools=new LinearLayout(this);Button find=button("איתור עסקה",blue,Color.WHITE);find.setOnClickListener(v->showTransactionSearch());tools.addView(find,new LinearLayout.LayoutParams(0,dp(54),1));Button clear=button("כל העסקאות",Color.WHITE,blue);clear.setOnClickListener(v->{managementFilters=new JSONObject();managementPage=0;loadManagementSales();});tools.addView(clear,new LinearLayout.LayoutParams(0,dp(54),1));Button sort=button("מיון",Color.WHITE,blue);sort.setOnClickListener(v->{managementSort=(managementSort+1)%4;managementPage=0;loadManagementSales();});tools.addView(sort,new LinearLayout.LayoutParams(0,dp(54),1));content.addView(tools);
        Button productsSummary=button("סיכום לפי מוצר",Color.WHITE,blue);productsSummary.setOnClickListener(v->showProductActivitySummaryNative());content.addView(productsSummary);
        managementResults=baseRoot();content.addView(managementResults);loadManagementSales();
    }
    private void showTransactionSearch(){
        ScrollView scroll=new ScrollView(this);LinearLayout box=baseRoot();box.setPadding(dp(14),dp(8),dp(14),dp(8));scroll.addView(box);
        String[] keys={"p_from","p_to","p_last4","p_product","p_min","p_max","p_reference","p_method"};String[] titles={"מתאריך YYYY-MM-DD","עד תאריך YYYY-MM-DD","4 ספרות אחרונות","מוצר שנרכש","סכום מינימלי","סכום מרבי","מספר עסקה או אסמכתא","אמצעי תשלום"};EditText[] inputs=new EditText[keys.length];
        for(int i=0;i<keys.length;i++){box.addView(label(titles[i]));inputs[i]=input(titles[i]);if(!managementFilters.isNull(keys[i]))inputs[i].setText(managementFilters.optString(keys[i],""));if(i==2){inputs[i].setInputType(InputType.TYPE_CLASS_NUMBER);inputs[i].setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(4)});}if(i==4||i==5)inputs[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(inputs[i]);}
        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("איתור עסקה").setView(scroll).setNegativeButton("ביטול",null).setPositiveButton("חפש",null).create();dlg.setOnShowListener(v->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{JSONObject next=new JSONObject();for(int i=0;i<keys.length;i++){String value=inputs[i].getText().toString().trim();if(i==2&&!value.isEmpty()&&!value.matches("[0-9]{4}"))throw new Exception("יש להזין ארבע ספרות");if((i==0||i==1)&&!value.isEmpty()&&!value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw new Exception("תאריך במבנה YYYY-MM-DD");next.put(keys[i],value.isEmpty()?JSONObject.NULL:(i==4||i==5)?Double.parseDouble(value):value);}managementFilters=next;managementPage=0;dlg.dismiss();loadManagementSales();}catch(Exception e){Toast.makeText(this,safeMsg(e),Toast.LENGTH_LONG).show();}}));dlg.show();
    }
    private void loadManagementSales(){
        final LinearLayout host=managementResults;if(host==null)return;final int revision=++managementRevision;host.removeAllViews();host.addView(text("טוען...",16,false));
        try{JSONObject body=new JSONObject(managementFilters.toString());body.put("p_page",managementPage);body.put("p_sort",managementSort);io.execute(()->{try{JSONObject data=new JSONObject(requestRaw("POST","/rest/v1/rpc/search_store_sales",body,true));main.post(()->{if(revision!=managementRevision||!host.isAttachedToWindow())return;host.removeAllViews();host.addView(text(String.format(Locale.ROOT,"סה״כ %.2f ₪ · %d עסקאות · %d יחידות",data.optDouble("total"),data.optInt("count"),data.optInt("units")),19,true));host.addView(compactAdminRow(new String[]{"תאריך","סכום","4 ספרות","פרטים"},new float[]{2,1.2f,1,1.5f},true,0));JSONArray rows=data.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject sale=rows.optJSONObject(i);if(sale==null)continue;String date=sale.optString("created_at").replace('T',' ');if(date.length()>16)date=date.substring(0,16);LinearLayout row=compactAdminRow(new String[]{date,String.format(Locale.ROOT,"%.2f ₪",sale.optDouble("total_amount")),sale.isNull("card_last4")?"—":sale.optString("card_last4"),""},new float[]{2,1.2f,1,1.5f},false,i);row.removeViewAt(3);Button details=button("פתיחת עסקה",Color.WHITE,blue);details.setTextSize(14);details.setOnClickListener(v->showNativeSaleDetails(sale));row.addView(details,new LinearLayout.LayoutParams(0,dp(48),1.5f));host.addView(row);}if(rows==null||rows.length()==0)host.addView(text("אין עסקאות התואמות לחיפוש",17,false));int count=data.optInt("count");LinearLayout nav=new LinearLayout(this);Button prev=button("הקודם",Color.WHITE,blue),next=button("הבא",Color.WHITE,blue);prev.setEnabled(managementPage>0);next.setEnabled((managementPage+1)*50<count);prev.setOnClickListener(v->{managementPage--;loadManagementSales();});next.setOnClickListener(v->{managementPage++;loadManagementSales();});nav.addView(prev,new LinearLayout.LayoutParams(0,dp(50),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(50),1));host.addView(nav);});}catch(Exception e){main.post(()->{if(revision==managementRevision&&host.isAttachedToWindow()){host.removeAllViews();host.addView(text("טעינת העסקאות נכשלה: "+safeMsg(e),17,false));}});}});}catch(Exception ignored){}
    }
    private void showNativeSaleDetails(JSONObject sale){
        ScrollView scroll=new ScrollView(this);LinearLayout box=baseRoot();box.setPadding(dp(14),dp(10),dp(14),dp(10));scroll.addView(box);box.addView(text(String.format(Locale.ROOT,"סכום: %.2f ₪",sale.optDouble("total_amount")),21,true));box.addView(text("תאריך: "+sale.optString("created_at"),16,false));box.addView(text("4 ספרות אחרונות: "+(sale.isNull("card_last4")?"לא התקבל מידע":sale.optString("card_last4")),17,true));box.addView(text("אסמכתא: "+(sale.isNull("payment_reference")?"—":sale.optString("payment_reference")),16,false));box.addView(text("מספר עסקה: "+sale.optString("id"),14,false));JSONArray items=sale.optJSONArray("items");if(items==null)items=new JSONArray();for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item!=null)box.addView(text(item.optString("product_name")+" × "+item.optInt("quantity")+" · "+String.format(Locale.ROOT,"%.2f ₪ ליחידה · סה״כ %.2f ₪",item.optDouble("unit_price"),item.optDouble("line_total")),17,false));}new AlertDialog.Builder(this).setTitle("פרטי עסקה").setView(scroll).setPositiveButton("סגור",null).show();
    }
    private void addManagementDashboard(){
        LinearLayout row=new LinearLayout(this);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);TextView[] amounts=new TextView[3];String[] titles={"מכירות היום","סה״כ החודש","סה״כ כללי"};int[] colors={Color.rgb(231,242,244),Color.rgb(229,245,236),Color.rgb(231,246,251)};
        for(int i=0;i<3;i++){LinearLayout tile=baseRoot();tile.setPadding(dp(14),dp(16),dp(14),dp(16));tile.setBackground(roundRect(colors[i],colors[i],0,14));tile.addView(text(titles[i],15,true));amounts[i]=text("…",26,true);tile.addView(amounts[i]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(125),1);lp.setMargins(dp(4),dp(5),dp(4),dp(12));row.addView(tile,lp);}content.addView(row,0);io.execute(()->{try{JSONObject result=new JSONObject(requestRaw("POST","/rest/v1/rpc/get_store_sales_summary",new JSONObject(),true));main.post(()->{String[] keys={"today","month","all"};if(row.isAttachedToWindow())for(int i=0;i<3;i++)amounts[i].setText(String.format(Locale.ROOT,"%,.2f ₪",result.optDouble(keys[i])));});}catch(Exception e){main.post(()->{for(TextView value:amounts)value.setText("לא זמין");});}});
    }
    private void showFeedbackEmailSettings(){
        buildShell("הגדרות קבלת הודעות",this::showAdminHome,false);content.addView(label("מייל לקבלת הודעות מהאתר ומהאפליקציה"));EditText email=input("כתובת מייל");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);email.setTextDirection(View.TEXT_DIRECTION_LTR);content.addView(email);Button save=button("שמור כתובת מייל",green,Color.WHITE);save.setEnabled(false);content.addView(save);io.execute(()->{try{String raw=requestRaw("POST","/rest/v1/rpc/get_feedback_email_setting",new JSONObject(),true);String value=new org.json.JSONTokener(raw).nextValue().toString();main.post(()->{email.setText("null".equals(value)?"":value);save.setEnabled(true);});}catch(Exception e){main.post(()->Toast.makeText(this,"טעינת ההגדרה נכשלה",Toast.LENGTH_LONG).show());}});save.setOnClickListener(v->{String value=email.getText().toString().trim();if(!value.isEmpty()&&!android.util.Patterns.EMAIL_ADDRESS.matcher(value).matches()){email.setError("כתובת מייל לא תקינה");return;}save.setEnabled(false);io.execute(()->{try{JSONObject body=new JSONObject();body.put("p_email",value);requestRaw("POST","/rest/v1/rpc/set_feedback_email_setting",body,true);main.post(()->{save.setEnabled(true);Toast.makeText(this,"הכתובת נשמרה לאתר ולאפליקציה",Toast.LENGTH_LONG).show();});}catch(Exception e){main.post(()->{save.setEnabled(true);Toast.makeText(this,"שמירה נכשלה: "+safeMsg(e),Toast.LENGTH_LONG).show();});}});});
    }
    private String feedbackRequestId="",feedbackRequestMessage="";
    private void openCustomerFeedback(){
        EditText note=input("כתוב כאן הערה לחנות");note.setSingleLine(false);note.setMinLines(4);note.setGravity(Gravity.TOP|Gravity.RIGHT);note.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1000)});
        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("שליחת הערה לחנות").setView(note).setNegativeButton("ביטול",null).setPositiveButton("שלח",null).create();dlg.setOnShowListener(x->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String message=note.getText().toString().trim();if(message.length()<2){note.setError("כתוב את ההערה");return;}if(!message.equals(feedbackRequestMessage)){feedbackRequestMessage=message;feedbackRequestId=java.util.UUID.randomUUID().toString();}final String requestId=feedbackRequestId;dlg.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);io.execute(()->{try{JSONObject body=new JSONObject();body.put("message",message);body.put("request_id",requestId);JSONObject result=new JSONObject(requestRaw("POST","/functions/v1/customer-feedback-email",body,false));if(!result.optBoolean("saved",false))throw new Exception("save failed");main.post(()->{feedbackRequestId="";feedbackRequestMessage="";dlg.dismiss();Toast.makeText(this,"ההערה נשלחה. תודה!",Toast.LENGTH_LONG).show();});}catch(Exception e){main.post(()->{dlg.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);Toast.makeText(this,"לא הצלחנו לשלוח. נסה שוב.",Toast.LENGTH_LONG).show();});}});}));dlg.show();
    }
    private int managementFinancePage=0;
    private String managementFinanceFrom="",managementFinanceTo="";
    private void showFinanceAdmin(){
        buildShell("הכנסות והוצאות",this::showAdminHome,false);final LinearLayout host=content;
        Button add=button("+ הוספת תנועה",green,Color.WHITE);add.setOnClickListener(v->financeDialog(null));host.addView(add);
        LinearLayout filters=new LinearLayout(this);EditText from=input("מתאריך YYYY-MM-DD"),to=input("עד תאריך YYYY-MM-DD");from.setText(managementFinanceFrom);to.setText(managementFinanceTo);filters.addView(from,new LinearLayout.LayoutParams(0,-2,1));filters.addView(to,new LinearLayout.LayoutParams(0,-2,1));host.addView(filters);Button apply=button("סינון תאריכים",blue,Color.WHITE);apply.setOnClickListener(v->{managementFinanceFrom=from.getText().toString().trim();managementFinanceTo=to.getText().toString().trim();managementFinancePage=0;showFinanceAdmin();});host.addView(apply);
        io.execute(()->{try{JSONObject body=new JSONObject();body.put("p_from",managementFinanceFrom.isEmpty()?JSONObject.NULL:managementFinanceFrom);body.put("p_to",managementFinanceTo.isEmpty()?JSONObject.NULL:managementFinanceTo);body.put("p_page",managementFinancePage);JSONObject data=new JSONObject(requestRaw("POST","/rest/v1/rpc/get_store_finance",body,true));main.post(()->{if(content!=host)return;double income=data.optDouble("income"),expense=data.optDouble("expense");host.addView(text(String.format(Locale.ROOT,"הכנסות: %.2f ₪ | הוצאות: %.2f ₪ | יתרה: %.2f ₪",income,expense,income-expense),20,true));JSONArray rows=data.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject entry=rows.optJSONObject(i);if(entry==null)continue;LinearLayout c=card();boolean auto=entry.optBoolean("automatic");c.addView(text(entry.optString("entry_date")+" · "+("income".equals(entry.optString("entry_type"))?"הכנסה":"הוצאה")+" · "+String.format(Locale.ROOT,"%.2f ₪",entry.optDouble("amount"))+"\n"+entry.optString("description")+(auto?" · ממכירות":""),17,true));if(!auto){Button edit=button("עריכה",Color.WHITE,blue);edit.setOnClickListener(v->financeDialog(entry));c.addView(edit);if(!"purchase".equals(entry.optString("source_type"))){Button del=button("מחיקה",red,Color.WHITE);del.setOnClickListener(v->deleteFinanceEntry(entry.optString("id")));c.addView(del);}}host.addView(c);}LinearLayout nav=new LinearLayout(this);Button prev=button("הקודם",Color.WHITE,blue),next=button("הבא",Color.WHITE,blue);prev.setEnabled(managementFinancePage>0);next.setEnabled((managementFinancePage+1)*100<data.optInt("count"));prev.setOnClickListener(v->{managementFinancePage--;showFinanceAdmin();});next.setOnClickListener(v->{managementFinancePage++;showFinanceAdmin();});nav.addView(prev,new LinearLayout.LayoutParams(0,dp(50),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(50),1));host.addView(nav);});}catch(Exception e){main.post(()->{if(content==host)host.addView(text("טעינת התנועות נכשלה: "+safeMsg(e),17,false));});}});
    }
